const paintAnatomy=(svg,state=[],allowed=null,prefix='anatomy-')=>{
 const defs='<defs>'+rankGradientDefs(prefix)+'</defs>';
 svg=svg.replace(/(<svg\b[^>]*>)/,'$1'+defs);
 const usedIds={};svg=svg.replace(/id="([^"]+)"/g,(m,id)=>{const base=prefix+id,n=(usedIds[base]||0)+1;usedIds[base]=n;return 'id="'+base+(n>1?'-'+n:'')+'"'});
 const list=Array.isArray(state)?state:[];
 return svg.replace(/<g class="muscle-zone-group" data-muscles="([^"]+)">/g,(_,id)=>{
  if(allowed && !allowed.has(id))return '';
  const st=list.find(x=>x.id===id);
  const i=st?.i??-1;
  const c=i>=0?rankColor(i):lockedTone(id);
  const a=i>=0?.94:.62;
  return '<g class="muscle-zone-group '+(i>=0?'unlocked':'locked')+'" data-muscles="'+id+'" style="--mc:'+c+';--ma:'+a+'">';
 });
};
